5}is {\\k34}Grade {\\k35}1.\nDialogue:0,0:00:50.57,0:00:51.23,Default,,0,0,0,,{\\k66}Wow!\nDialogue:0,0:00:51.46,0:00:52.45,Default,,0,0,0,,{\\k16}I {\\k13}am {\\k70}twelve.\nDialogue:0,0:00:52.65,0:00:53.92,Default,,0,0,0,,{\\k17}We {\\k11}are {\\k7}in {\\k7}the {\\k31}same {\\k54}grade!\nDialogue:0,0:00:56.86,0:00:58.40,Default,,0,0,0,,{\\k17}Do {\\k10}you {\\k13}go {\\k7}to {\\k35}school {\\k19}by {\\k53}bus?\nDialogue:0,0:01:0.41,0:01:2.07,Default,,0,0,0,,{\\k65}Yes, {\\k14}I {\\k16}go {\\k17}by {\\k52}bus.\nDialogue:0,0:01:2.29,0:01:2.93,Default,,0,0,0,,{\\k64}Cool!\nDialogue:0,0:01:3.03,0:01:3.76,Default,,0,0,0,,{\\k11}I {\\k12}go {\\k13}on {\\k37}foot.\nDialogue:0,0:01:3.86,0:01:5.15,Default,,0,0,0,,{\\k17}My {\\k32}house {\\k6}is {\\k19}near {\\k9}the {\\k46}school.\nDialogue:0,0:01:9.26,0:01:10.42,Default,,0,0,0,,{\\k25}My {\\k27}name {\\k16}is {\\k48}Tom.\nDialogue:0,0:01:10.61,0:01:11.43,Default,,0,0,0,,{\\k22}I {\\k14}am {\\k46}eleven.\nDialogue:0,0:01:11.67,0:01:12.90,Default,,0,0,0,,{\\k15}My {\\k34}class {\\k12}is {\\k32}Class {\\k30}1.\nDialogue:0,0:01:13.00,0:01:14.31,Default,,0,0,0,,{\\k14}I {\\k14}go {\\k12}to {\\k22}school {\\k18}by {\\k51}bus.\nDialogue:0,0:01:14.46,0:01:15.19,Default,,0,0,0,,{\\k73}Perfect!\nDialogue:0,0:01:15.29,0:01:16.43,Default,,0,0,0,,{\\k26}Now {\\k13}we {\\k8}are {\\k67}friends!\nDialogue:0,0:01:16.83,0:01:19.95,Default,,0,0,0,,{\\k27}Let's {\\k39}go{\\k142} {\\k20}on {\\k8}the {\\k76}swings!\nDialogue:0,0:01:20.05,0:01:22.76,Default,,0,0,0,,{\\k28}His {\\k27}name {\\k14}is {\\k54}Tom, {\\k19}and {\\k18}he {\\k13}is {\\k17}my {\\k77}friend!\nDialogue:0,0:01:22.86,0:01:23.55,Default,,0,0,0,,{\\k69}Yes!\nDialogue:0,0:01:23.71,0:01:27.15,Default,,0,0,0,,{\\k18}And {\\k19}her {\\k53}name.{\\k10}{\\k1}.{\\k9}{\\k1}.{\\k10}{\\k35}oh, {\\k15}I {\\k30}mean, {\\k32}his {\\k22}name {\\k13}is {\\k57}Leo!",
  "translateAss": [
    {
      "lang": "zh",
      "text": "Dialogue:0,0:00:2.31,0:00:3.81,Default,,0,0,0,,嗯...他是谁啊？\nDialogue:0,0:00:4.16,0:00:7.05,Default,,0,0,0,,他的名字...呃...我不知道他叫什么。\nDialogue:0,0:00:7.70,0:00:10.35,Default,,0,0,0,,嗨！我叫Leo。你叫什么名字呀？\nDialogue:0,0:00:14.99,0:00:18.81,Default,,0,0,0,,嗯...那个...\nDialogue:0,0:00:18.91,0:00:19.41,Default,,0,0,0,,没关系！\nDialogue:0,0:00:19.51,0:00:20.03,Default,,0,0,0,,再说一遍试试。\nDialogue:0,0:00:20.13,0:00:20.84,Default,,0,0,0,,我叫Leo。\nDialogue:0,0:00:20.94,0:00:21.66,Default,,0,0,0,,你叫什么名字呢？\nDialogue:0,0:00:22.98,0:00:26.01,Default,,0,0,0,,我...那个...我叫Tom。\nDialogue:0,0:00:26.11,0:00:27.15,Default,,0,0,0,,太棒了！\nDialogue:0,0:00:27.25,0:00:29.86,Default,,0,0,0,,你的名字是Tom。\nDialogue:0,0:00:32.78,0:00:34.79,Default,,0,0,0,,他叫Tom！\nDialogue:0,0:00:34.79,0:00:34.79,Default,,0,0,0,,来，说一遍：“我叫Tom。”\nDialogue:0,0:00:35.28,0:00:35.83,Default,,0,0,0,,我叫...呃...Tom。\nDialogue:0,0:00:35.93,0:00:37.01,Default,,0,0,0,,Tom，你今年多大啦？\nDialogue:0,0:00:37.11,0:00:45.71,Default,,0,0,0,,还有，你在哪个班呢？\nDialogue:0,0:00:46.15,0:00:46.99,Default,,0,0,0,,我十一岁了。\nDialogue:0,0:00:47.45,0:00:48.74,Default,,0,0,0,,我在一班。\nDialogue:0,0:00:48.92,0:00:50.31,Default,,0,0,0,,我是一年级的。\nDialogue:0,0:00:50.57,0:00:51.23,Default,,0,0,0,,哇！\nDialogue:0,0:00:51.46,0:00:52.45,Default,,0,0,0,,我十二岁了。\nDialogue:0,0:00:52.65,0:00:53.92,Default,,0,0,0,,我们居然是同一个年级的！\nDialogue:0,0:00:56.86,0:00:58.40,Default,,0,0,0,,你平时是坐公交车上学的吗？\nDialogue:0,0:01:0.41,0:01:2.07,Default,,0,0,0,,对呀，我坐公交车。\nDialogue:0,0:01:2.29,0:01:2.93,Default,,0,0,0,,真酷！\nDialogue:0,0:01:3.03,0:01:3.76,Default,,0,0,0,,我是走路上学的。\nDialogue:0,0:01:3.86,0:01:5.15,Default,,0,0,0,,我家离学校很近。\nDialogue:0,0:01:9.26,0:01:10.42,Default,,0,0,0,,我叫Tom。\nDialogue:0,0:01:10.61,0:01:11.43,Default,,0,0,0,,我十一岁。\nDialogue:0,0:01:11.67,0:01:12.90,Default,,0,0,0,,我在一班。\nDialogue:0,0:01:13.00,0:01:14.31,Default,,0,0,0,,我坐公交车上学的。\nDialogue:0,0:01:14.46,0:01:15.19,Default,,0,0,0,,说得真好！\nDialogue:0,0:01:15.29,0:01:16.43,Default,,0,0,0,,现在我们是朋友啦！\nDialogue:0,0:01:16.83,0:01:19.95,Default,,0,0,0,,走，我们去荡秋千吧！\nDialogue:0,0:01:20.05,0:01:22.76,Default,,0,0,0,,他叫Tom，而且他是我朋友！\nDialogue:0,0:01:22.86,0:01:23.55,Default,,0,0,0,,没错！\nDialogue:0,0:01:23.71,0:01:27.15,Default,,0,0,0,,还有她的名字...哎呀，我是说，他叫Leo！"
    }
  ]
} 
*/

