      data['pronunciations'] = arr0;
    }
    data['favorited'] = favorited;
    data['video'] = video?.toJson();
    return data;
  }

  String? _resolveScriptContentFromAss() {
    if (contentType != 'SCRIPT') return null;
    final assText = audioInfo?.audioAss;
    if (assText == null || assText.trim().isEmpty) return null;
    final sentences = KaraokeSubtitlesUtils.parseAssSentenceByDialogue(assText);
    if (sentences.isEmpty) return null;
    final lines = sentences
        .map((sentence) => sentence.words.map((word) => '${word.leftSpace}${word.text}${word.rightSpace}').join().trim())
        .where((line) => line.isNotEmpty)
        .toList();
    if (lines.isEmpty) return null;
    return lines.join('\n');
  }
}

